import{_ as r,o as l,c as a,ai as o}from"./chunks/framework.CAnUr3M0.js";const d=JSON.parse('{"title":"HTML 基础","description":"","frontmatter":{},"headers":[],"relativePath":"browser/html.md","filePath":"browser/html.md"}'),e={name:"browser/html.md"};function i(n,t,s,h,g,u){return l(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="html-基础" tabindex="-1">HTML 基础 <a class="header-anchor" href="#html-基础" aria-label="Permalink to &quot;HTML 基础&quot;">​</a></h1><blockquote><p>HTML/XML/XHTML · 元素分类 · 语义化 · property vs attribute · 本地存储 · 图片格式</p></blockquote><hr><h2 id="一、html-xml-xhtml-区别" tabindex="-1">一、HTML / XML / XHTML 区别 <a class="header-anchor" href="#一、html-xml-xhtml-区别" aria-label="Permalink to &quot;一、HTML / XML / XHTML 区别&quot;">​</a></h2><ul><li><strong>HTML</strong>：语法较松散的 Web 标记语言</li><li><strong>XML</strong>：可扩展标记语言，用于存储数据和结构</li><li><strong>XHTML</strong>：基于 XML，语法更严格（标签小写、必须闭合、正确嵌套、必须有根元素）</li><li><strong>HTML5</strong>：HTML/XHTML/HTML DOM 的新标准，新增 canvas/video/audio/语义化标签/localStorage 等</li></ul><hr><h2 id="二、行内元素、块级元素、空元素" tabindex="-1">二、行内元素、块级元素、空元素 <a class="header-anchor" href="#二、行内元素、块级元素、空元素" aria-label="Permalink to &quot;二、行内元素、块级元素、空元素&quot;">​</a></h2><ul><li><strong>行内元素</strong>：a、b、span、img、input、select、strong</li><li><strong>块级元素</strong>：div、ul、li、dl、h1-h6、p</li><li><strong>空元素</strong>：br、hr、img、link、meta（无闭合标签）</li></ul><hr><h2 id="三、语义化标签" tabindex="-1">三、语义化标签 <a class="header-anchor" href="#三、语义化标签" aria-label="Permalink to &quot;三、语义化标签&quot;">​</a></h2><ul><li><strong>好处</strong>：去掉样式仍有清晰结构、利于 SEO、方便辅助设备解析、便于团队维护</li><li><strong>HTML5 新增</strong>：header、nav、footer、aside、article、section</li></ul><hr><h2 id="四、property-与-attribute-区别" tabindex="-1">四、property 与 attribute 区别 <a class="header-anchor" href="#四、property-与-attribute-区别" aria-label="Permalink to &quot;四、property 与 attribute 区别&quot;">​</a></h2><ul><li><strong>attribute</strong>：HTML 标签上的特性（id、class 等），值为字符串</li><li><strong>property</strong>：DOM 对象的属性（JS 对象属性），如 childNodes、firstChild</li></ul><hr><h2 id="五、html5-本地存储" tabindex="-1">五、HTML5 本地存储 <a class="header-anchor" href="#五、html5-本地存储" aria-label="Permalink to &quot;五、HTML5 本地存储&quot;">​</a></h2><ul><li><strong>localStorage</strong>：永久存储，除非手动删除，可达 5M+</li><li><strong>sessionStorage</strong>：会话级别，关闭浏览器后销毁，不跨窗口共享</li><li><strong>与 cookie 区别</strong>： <ul><li>cookie 每次 HTTP 请求都会携带，localStorage 不会</li><li>cookie 大小限制 4K，localStorage 更大</li><li>cookie 有过期时间，localStorage 永久</li></ul></li></ul><hr><h2 id="六、图片格式" tabindex="-1">六、图片格式 <a class="header-anchor" href="#六、图片格式" aria-label="Permalink to &quot;六、图片格式&quot;">​</a></h2><ul><li><strong>png</strong>：支持透明，颜色丰富，使用频率最高</li><li><strong>jpg/jpeg</strong>：不支持透明，可压缩，适合照片</li><li><strong>gif</strong>：支持动画，颜色较少</li></ul><hr><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./rendering.html">浏览器进程与渲染</a> — 多进程架构、渲染流程、复合层</li><li><a href="./network.html">网络协议与缓存</a> — HTTP/TCP、缓存、CDN</li><li><a href="./security.html">安全</a> — XSS、CSRF 防御</li></ul>',23)])])}const m=r(e,[["render",i]]);export{d as __pageData,m as default};
